globalThis.ANDE_CHUNKS["f5fb1f634e4a491fe3df054c9716ac3a772713d66153c738424f91e08bfabbc3"] = [{"id":"shlab_social:7446231036575648039","sourceKey":"shlab_social","company":"上海AI实验室","title":"重点研发项目经理TPM（大模型、AI4S）- 项目与资源管理中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7446231036575648039?mode=social","duty":"岗位职责：\n1. 负责科研团队重点研发项目工作推进，制定项目计划、推进项目执行、日常项目跟进、监控项目风险，确保目标达成；\n2. 统筹项目资源（设备、算力、人力等），发挥有限资源的最大化效益；\n3. 制定科研项目标准化立项与交付全流程，组织项目书撰写、阶段性检查、结题验收等工作；\n4. 支撑开展人工智能产业、科研等决策研究，参与相关文件的起草编制等；\n5. 协助策划、组织和实施科研侧的内外部会议、活动及大型赛事，包括但不限于政府、科研院所、产业界；\n6. 管理并跟进与重点企业、机构的合作，支持研究团队与外部沟通交流；\n7. 负责项目成果发布宣传工作，包括但不限于组织、跟踪、材料收集、对外链接、想法提出等；\n8. 协助项目团队组建，制定研发型项目管理方案与配套全流程，提升研发项目工作效率；\n9. 协助进行团队内部管理，进行团队建设，完善团队内部管理流程，并持续优化；\n\n职位要求：\n1. 硕士","requirements":"","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7464047091833604390","sourceKey":"shlab_social","company":"上海AI实验室","title":"重大任务项目经理人-项目经理人与成果转化中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7464047091833604390?mode=social","duty":"岗位概述：\n项目经理人的核心使命是在科学世界和产业世界之间架起桥梁，发现并推动具有战略突破潜力的创新项目，需要通过系统的价值发现、精准的团队评估、深度的项目共创，连接顶尖科学家、产业领袖和政策制定者，推动中国科技创新的战略突破。\n岗位职责：\n1. 战略级技术趋势研判与规划\n  1）主导AI for Science、大模型、具身智能等前沿技术的全球趋势分析，评估技术先进性、落地可执行性，制定技术战略路线。识别挑战既有共识、跨越学科边界的颠覆性创新机会；\n  2）深度参与实验室战略决策，结合业务需求与行业动态，输出技术投入优先级建议，支撑高层技术布局决策。\n2. 技术生态构建与资源整合\n  1）在全国范围内发现、评估并筛选优秀科研团队，超越论文数量、获奖数量等指标，深入理解团队的真实研究能力和价值；建立和维护前沿领域的专家顾问网络，定期组织跨界研讨会；\n  2）通过科研专项、算力支持、基金投资","requirements":"任职要求：\n1. 博士学历优先（特别优秀者可放宽到硕士），人工智能、计算机、物理、化学、材料、生物、医学等理工科专业优先；\n2. 以下任一方向3年及以上工作经验优先：\n  1）科研背景：有学术研究或科技管理/咨询工作经历，特别是跨学科合作经验；\n  2）投资背景：从事早期项目评估、天使投资等，具备识别潜力项目的敏感度；\n  3）产业背景：在高科技企业从事R&D管理、战略规划、技术评估工作，理解技术应用场景；\n  4）项目管理背景：有复杂项目协调推进经验，理解项目管理实质。\n3. 能够快速获取陌生领域核心知识，清晰表达复杂技术概念；\n4. 具备系统性思维，能从复杂信息中抽象核心问题，善于结构化分析；\n5. 谦虚、好奇，愿意从专家和实践中快速学习，乐于跨越舒适区，有推动科学进步的热情；\n6. 诚实、负责，尊重科学伦理，拒绝学术不诚实。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7493730371797453093","sourceKey":"shlab_social","company":"上海AI实验室","title":"科研规划管理（高峰、数据、智能体、大模型）- 科研规划中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7493730371797453093?mode=social","duty":"1. 领域战略规划与解码\n— 参与机构总体战略的制定与迭代，重点负责对二级单元进行战略解码，形成可执行、可衡量的业务发展路径、行动计划与技术路线图；\n— 参与设计并推动战略性业务发展方案，包括资源整合模式与阶段目标设定，确保战略有效落地；\n— 构建战略执行监控与反馈体系，定期开展复盘与校准，保障业务发展与机构宏观战略始终保持对齐。\n2. 领域战略研究与洞察\n— 围绕具体领域开展系统性研究，研判科技产业发展趋势、竞争格局与政策导向，撰写深度战略分析报告，为机构中长期发展决策提供支持；\n— 开展战略推演，进行战略假设验证与迭代跟踪，识别重大风险与战略机遇，定期向决策层提供战略预警和布局建议。\n3. 领域战略落地与业务赋能\n— 深度嵌入科研与业务团队，提供战略分析、路径规划和项目设计等全方位支持；\n— 建立跨单元、跨层级的协同流程，推动战略规划-战略解码-战略落地的一体化运作；\n— 根据业务需要","requirements":"1. 教育背景\n— 硕士及以上学历，人工智能、计算机科学、电子信息、管理科学与工程等理工科相关专业优先，欢迎复合交叉型人才；\n— 具备扎实的研究能力和系统性的思维框架，能够快速学习并掌握新领域知识。\n2. 专业经验\n— 硕士须具备4年以上科技领域战略规划、产业分析、商业咨询或科研管理相关经验，有头部科技企业、知名咨询公司或高水平研究机构工作经历者优先；博士工作年限不限；\n— 对人工智能、前沿信息技术或特定垂直领域具备深厚的行业认知与洞察，能独立开展系统性战略研判并形成可落地的战略建议；\n— 擅长战略研究、战略管理方法论，熟练掌握并实践多种战略分析与管理工具，具备从战略制定到执行推进的全流程经验。\n3. 核心能力\n— 战略思维能力强：能理解抽象的战略意图，将宏观战略转化为清晰可执行的业务方案和行动路径；识别战略执行中的偏差；从局部工作洞察全局价值；\n— 技术理解能力强：针对AI领域（大模型、","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7493888550514952459","sourceKey":"shlab_social","company":"上海AI实验室","title":"多模态大模型青年研究员/算法工程师","city":"上海","category":"算法类","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7493888550514952459?mode=social","duty":"1. 参与科学多模态大模型的研发，包括但不限于预训练、后训练和评测体系构建。\n2. 参与大模型训练与知识图谱，检索增强生成，多模态学习，强化学习（Reinforcement Learning) 等技术的创新融合；\n3. 构建高质量的大模型数据集，包括但不限于文本，图片，视频，多组学，时空间序列等数据；\n4. 参与大模型技术在科学场景的落地应用。","requirements":"1. 人工智能相关专业，具备扎实的编程与算法基础，科研或工程能力优秀，有产业工作经验优先；\n2. 熟悉人工智能领域的相关研究工作和算法，具有多模态大模型实践经验，具备大模型优化能力优先；\n3. 具备优秀的分析和解决问题能力，良好的团队合作精神及沟通意识。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7519329796603332901","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI测试开发工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7519329796603332901?mode=social","duty":"1. 独立负责大模型应用产品及 AI 系统的测试开发工作\n2. 全面把握产品功能和非功能质量，对交付质量负责\n3. 负责测试全流程的自动化流水线建设，进行测试方法、测试框架平台等方面的创新和落地\n4. 负责产品迭代中把控研发、测试以及交付过程质量，以及流程质量规范实施","requirements":"1. 计算机及相关专业本科以上学历，在开发测试领域有一年及以上经验\n2. 熟悉测试流程和测试方案设计，熟悉测试自动化开发以及主流 CI 工具框架使用，对自动化需求挖掘、方案设计和实施有深刻认识\n3. 拥有良好的团队协作和沟通能力，较强的质量意识\n4. 在 AI 系统或 AI 应用测试开发、评测等领域开发测试经验者优先","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7535362154582575406","sourceKey":"shlab_social","company":"上海AI实验室","title":"重点研发项目经理TPM（安全）- 项目与资源管理中心","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7535362154582575406?mode=social","duty":"岗位职责：\n1. 负责科研团队重点研发项目工作推进，制定研发型项目管理方案与配套全流程，提升研发项目工作效率并推动落地；协调内外部资源(产研团队、合作企业、政府等相关部门)，确保项目进度、质量与成本可控；识别项目风险，提供预案并解决跨部门协作问题，保障项目按期交付；\n2.支撑科研项目标准化立项与交付全流程，组织项目书撰写、阶段性检查、结题验收等工作；\n3.支持组织管理与运营，包括但不限于团队资源配置与资源协调（设备、算力、人力等）、知识库建设、效能优化等；\n4.支撑开展人工智能产业、科研等决策研究，参与相关文件的起草编制等；\n5.管理并跟进与重点企业、机构的合作，支持研究团队与外部沟通交流。\n\n职位要求:\n1.硕士及以上学历，3年及以上相关工作经验，人工智能、计算机等理工科相关专业优先；\n2.拥有出色的沟通协调能力与跨部门合作能力，能够与不同部门、不同层级的人员进行良好的沟通与协作，协调各","requirements":"","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7540111744543443250","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型应用算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7540111744543443250?mode=social","duty":"1、利用主流AI工具及开发框架，完成解决方案的产品原型开发、测试及优化，确保技术方案的可落地性与创新性\n2、研究相关领域的大模型核心技术，包括：知识与数据的建模与融合、面向设计场景的模型后训练（SFT、PEFT、RLHF等）、结合RAG与智能体（Agent）框架的决策推理\n3、负责垂直领域大模型的训练与优化，包括需求分析、数据集构建清洗合成、模型训练及评估迭代\n4、搭建并优化智能体系统，实现基于模型和算法的辅助决策与自动化\n5、跟踪行业前沿算法，参与面向场景的算法研究与创新，推动相关成果落地 ","requirements":"1、本科及以上学历，计算机科学、人工智能、电子信息等相关专业优先\n2、具有扎实的编程与工程开发能力，熟悉Python、PyTorch，有大模型训练实操经验者优先\n3、具备相关领域知识背景，熟悉工业设计流程与关键技术，能够与大模型技术深度结合\n4、熟悉大模型（LLM、MLLM）底层原理、主流训练框架和技术路线，具备模型训练与部署能力\n5、熟悉RAG、Agent框架及Prompt优化技术，有实际项目经验者优先\n6、发表高质量学术论文或参与过优秀开源项目开发维护者优先","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7553291568346728758","sourceKey":"shlab_social","company":"上海AI实验室","title":"智能体算法工程师/青年研究员","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7553291568346728758?mode=social","duty":"1. 参与书生大模型智能体能力建设，负责Agent在搜索、工具调用、生产力办公、代码生成、安全攻防、科学研究等场景下的算法研发与系统实现。\n2. 构建面向复杂任务的智能体训练数据，包括任务轨迹、工具调用链、环境交互数据、多轮推理数据、代码执行数据、安全攻防数据及科学任务数据等。\n3. 研发和优化Agent相关模型能力，包括任务规划、多步推理、长上下文理解、函数调用、工具使用、代码执行、结果校验、自我反思与错误恢复等能力。\n4. 建设智能体评测体系与自动化评测流水线，围绕BrowseComp、SWE-Bench、安全攻防Bench、DeepResearch等任务开展模型能力评测、问题分析和迭代优化。\n5. 推动智能体能力与主线基座模型合版集成，参与模型训练、后训练、数据治理、能力回归和版本交付工作。\n6. 跟踪国内外Agent、代码大模型、安全智能体、科学智能体等前沿技术进展，完成技术调研、","requirements":"任职要求\n1. 计算机、人工智能、软件工程、网络安全、自然语言处理、机器学习、数据科学、物理、化学、生物、材料等相关专业硕士及以上学历，优秀本科生亦可考虑。\n2. 熟悉大语言模型、Agent、RAG、Tool Use、代码生成、强化学习、后训练、数据合成或自动化评测中的一个或多个方向。\n3. 具备扎实的编程能力，熟练使用Python，熟悉PyTorch、Transformers、vLLM、Ray、Docker、Linux等常用训练与工程工具者优先。\n4. 具备以下经验之一者优先：\n  - 参与过大模型训练、SFT、RLHF/RLAIF、DPO、数据合成或评测体系建设；\n  - 参与过Agent系统、工具调用系统、自动化办公助手、搜索问答系统建设；\n  - 熟悉SWE-Bench、代码生成、代码修复、仓库级代码理解或自动化软件工程；\n  - 熟悉CTF、漏洞挖掘、渗透测试、二进制分析、代码安","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7555027739335461139","sourceKey":"shlab_social","company":"上海AI实验室","title":"材料大模型青年研究员/算法工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7555027739335461139?mode=social","duty":"我们正在寻找一位在生成模型与几何深度学习（Geometric Deep Learning）方面拥有深厚背景的人工智能研究员，希望您在扩散模型（Diffusion Models）、图神经网络（Graph Neural Networks）相关及交叉领域具备扎实的理论与实践经验。您将负责领导设计和推进我们的生成式AI算法，专注于其在通用科学领域的应用。\n岗位职责\n1. 深入开展理论算法分析，研究、设计、实现适用于基座模型的架构（如合适的扩散模型和等变图神经网络模型等），并推进其实现与应用；\n2. 结合不同模型的特点，探索多模态、Graph与LLM的融合方法，提升模型表达能力与跨模态推理能力；\n3. 与化科学领域专家协作，将前沿技术应用于关键科学问题，推动AI驱动的科研创新。","requirements":"任职要求\n1. 拥有计算机科学、机器学习、应用数学或相关领域的博士学历（或硕士学历且拥有3年以上相关研发经验）；\n2. 熟练掌握PyTorch等深度学习框架，对Transformer等主流模型有深入理解；熟悉GNN（如MPNN, SchNet, DimeNet, GemNet）及等变神经网络（e3nn, SE(3)-Transformer）的设计与实现；\n3. 能实现高效代码转换，熟悉标准的MLOps工具链（如Git, Docker），具备Diffusion Models，Score-based model，Flow matching等生成模型扎实的理论基础和丰富的实战经验；\n4. 具有出色的数学基础（概率论、随机过程、优化理论），并能一作在顶级会议（NeurIPS, ICML, ICLR）或期刊（TPAMI，Nature/Cell/Science及其子刊）上发表过相关论文。\n5. 具备优","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7555079128825104681","sourceKey":"shlab_social","company":"上海AI实验室","title":"系统TesT","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7555079128825104681?mode=social","duty":"Test","requirements":"Test","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7555353313010223401","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型评测算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7555353313010223401?mode=social","duty":"1. 参与大模型评测算法的设计与开发，构建贴近用户真实场景的评测基准，涵盖纯文本、图文、视频、Agent等多种场景。\n2. 探索并落地评测分析能力，挖掘模型问题，提出改进建议，支持模型优化迭代。\n3. 调研AI领域最新技术，协助团队引入创新评测方法。\n5. 跟踪AI领域前沿技术，团队协作，完成算法评测相关科研任务。\n","requirements":"1. 计算机、人工智能或相关专业硕士及以上学历，具备算法理论基础。\n2. 研究方向聚焦LLM、MLLM、Agent相关领域，该领域有代表性科研成果。\n3. 具备丰富的大模型或Agent算法评测经验，熟悉CV或NLP评测方法。\n4. 熟悉Python、TensorFlow或PyTorch等开发工具，了解LLM、MLLM、Agent部署等，了解自动化测试流程。\n5. 具备较强的数据分析能力和团队协作意识，善于解决技术问题。\n6. 具备出色的逻辑思维、独立思考能力、分析能力和快速学习能力、对大模型前沿动向有足够的热情和好奇心。\n7. 以上条件满足3点即可。在ICLR、ICML、ACL等顶会发表过论文者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7563274661065886006","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型训练框架算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7563274661065886006?mode=social","duty":"1、分布式训练框架开发：主导或深度参与书生系列大模型训练框架的设计、实现与迭代，覆盖多种任务（预训练、SFT、RL等）和多种模态（语言、视频、音频等）。\n2、性能极致优化：深入分析训练瓶颈，对计算（GPU/NPU）、通信（NCCL/RDMA）、存储（IO）和内存进行系统性优化，包括不限于算子融合、显存优化等技术。\n3、稳定性与可靠性保障：构建高可用的训练系统，确保超大规模集群上长时间训练的稳定性。\n协作与支持：与模型研究团队紧密合作，理解其需求并将其转化为框架特性，为研究员提供高性能训练解决方案和技术支持。\n4、技术前瞻性研究：跟踪业界最新技术动态，探索并引入新的并行策略、编译技术和硬件协同设计，保持框架的技术领先性。","requirements":"1、计算机科学、人工智能或相关领域的本科及以上学历。\n2、拥有PyTorch开发或深度定制经验，熟悉其自动微分、计算图、张量计算等核心机制。\n3、有使用Deepspeed、FSDP、Megatron等框架进行大模型分布式训练的实际项目经验。\n\n加分项：\n1、熟悉GPU/NPU硬件架构，有CUDA/OpenMPI内核开发或性能剖析经验（使用Nsight, Triton等工具）。\n2、具备分布式系统知识，熟悉NCCL、MPI、gRPC等通信库，对RDMA有了解者优先。\n3、参与过知名深度学习框架（PyTorch, TensorFlow）或大规模分布式训练系统的开源贡献。\n4、强烈的责任心、出色的分析和解决复杂问题的能力，对高性能计算充满热情。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7574396982888139014","sourceKey":"shlab_social","company":"上海AI实验室","title":"生命科学青年研究员/算法工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7574396982888139014?mode=social","duty":"1. 负责面向生命科学的多模态大模型设计与训练。融合生物医学文献、组学及分子结构数据，构建兼具科学推理能力与微观物理表征能力的基座模型，支持蛋白质、核酸及小分子等场景的研究；\n2. 设计专用于生命科学研究的智能体协作模式，模拟科研专家的思考路径。例如：构建能自动拆解复杂生物学问题、执行深度文献调研、构建知识图谱、提出科学假设的Agent系统；\n3. 探索大模型在生物通路分析、靶点发现、作用机理推演等场景下的长链条推理能力，提升科学结论的可解释性与准确性；\n4. 跟踪 AI4S 领域动态，参与团队技术讨论，针对生命科学领域重要的问题提出创新 AI 解决方案, 推动技术在真实科研场景中的落地。","requirements":"1.教育背景：计算机科学、人工智能、或计算生物、计算化学背景但具备扎实深度学习能力的硕士/博士；\n2.熟悉大模型、多智能体优化相关理论；对大语言模型（如 GPT 系列、Transformer 架构）或者 AlphaFold、ESM 等生物大模型原理有深入理解；\n3.具有很强的发现问题、解决问题的能力，以及扎实的 Coding 实现能力（Python/PyTorch；\n4.相信AGI, 热爱科学探索，具备极强的问题拆解能力，愿意为了解决生命科学的本质问题而不断拓展技术边界，致力于用 AI 加速生命科学的新突破。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7579187048109869375","sourceKey":"shlab_social","company":"上海AI实验室","title":"解决方案顾问","city":"上海","category":"业务通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7579187048109869375?mode=social","duty":"岗位说明：\n结合实验室的科研方向和科研成果完成应用场景发掘、梳理和设计\n深度参与AI相关的解决方案设计与文档编写，并结合客户需求完成业务方案和技术方案的细化\n协助团队完成客户技术交流，通过原型演示等方式清晰传递方案价值，推动项目落地\n跟踪全球AI技术动态及行业应用趋势，形成结构化的研究报告，支撑业务决策\n\n","requirements":"职位要求：\n5年以上相关工作经验；具有制造、金融、供应链、能源领域管理咨询经验优先\n精通Office办公软件，擅长结构化表达复杂技术逻辑，具备高质量方案文档编写经验优先\n具备优秀的沟通能力、团队协作意识及快速学习能力，对AI技术应用场景有敏锐洞察力\n硕士及以上学历，计算机科学、人工智能、电子信息、数学等相关专业优先\n","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7585174467577874739","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI基础设施研究员/工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7585174467577874739?mode=social","duty":"1. 负责大模型训练所需的底层基础设施建设与维护，包括 GPU 集群、存储系统、任务调度与资源管理等；\n2. 与训练工程、模型研究团队合作，优化分布式训练作业的部署流程，提高集群资源利用率与稳定性；\n3. 搭建训练任务的监控与告警体系，对 GPU 利用率、网络带宽、IO 性能等关键指标进行观测和调优；\n4. 参与建设内部 AI 平台工具（如一键提任务、实验管理、日志系统等），提升研发团队整体效率；\n5. 编写并维护相关技术文档和运维手册，持续改进系统的可靠性与可维护性。","requirements":"1. 计算机、软件工程、网络工程等相关专业硕士及以上学历；\n2. 熟悉 Linux 操作系统，精通至少一种后端编程语言（如 Python / Go / C++），有分布式系统开发经验；\n3. 熟悉主流容器与编排技术（Docker、Kubernetes 等），了解常见任务调度与资源管理框架（如 Slurm、K8s Operator 等）者优先；\n4. 对GPU计算、分布式训练、网络与存储有基本理解，有大规模训练平台或云原生平台建设经验者优先；\n5. 具备良好的问题定位与性能调优能力，能在复杂系统中快速排查并解决问题；\n6. 具备良好的沟通与协作能力，能够支持多团队协同工作。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7585176321564166451","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型架构研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7585176321564166451?mode=social","duty":"1. 负责新一代大模型架构的设计与验证，包括但不限于 Transformer 替代架构、混合架构、记忆增强架构等；\n2. 围绕长上下文、记忆能力、持续学习能力等关键方向，设计实验方案并与现有 Transformer 基线进行系统对比；\n3. 将研究原型工程化，与训练工程、Infra 团队协作，完成从小规模原型到 8B 级模型的端到端实验流程；\n4. 持续跟踪国内外前沿研究和开源项目，评估技术路线可行性，并提出架构演进建议了；\n5. 输出技术文档和内部分享，沉淀模型架构设计规范、实验结论和最佳实践。","requirements":"1. 计算机科学、数学、电子工程等相关专业硕士及以上学历，博士优先；\n2. 扎实的深度学习理论基础，熟悉主流大模型架构（Transformer、Mamba/SSM、RNN/RWKV 等）及其变体；\n3. 在下述至少一类方向有深入经验：模型架构设计、长序列建模、记忆机制、持续学习 / 终身学习；\n4. 熟练使用 PyTorch / TensorFlow 等深度学习框架，有从 0 到 1 搭建模型结构和训练代码的经验；\n5. 具备较强的科研能力和工程落地能力，有顶会论文或大规模模型项目经验者优先；\n6. 具备良好的沟通协作能力和自驱力，乐于在不确定性较高的前沿方向探索。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7585179064547690778","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型数据算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7585179064547690778?mode=social","duty":"1. 负责大模型预训练与微调数据的构建，包括数据采集、清洗、去重、过滤、打标、质量评估等全流程；\n2. 构建高效的数据处理与分发管道，支持 TB–PB 级数据量的处理与管理；\n3. 开发数据质量监控体系，识别低质量、有害、重复、偏见数据并进行修复；\n4. 与训练团队协作，通过数据实验发现提升路径，持续优化数据方案。","requirements":"1. 熟练掌握 Python / SQL / Spark / Ray 等数据处理工具；\n2. 熟悉互联网文本数据、数据过滤策略、语言模型数据构建规范；\n3. 有自动化数据清洗、文本分类、质量检测等经验者优先；\n4. 具备团队协作和文档能力，能维护清晰的数据版本和数据血缘。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7585179885099944238","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型攻防算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7585179885099944238?mode=social","duty":"1. 研究并构造针对大语言模型的攻击方法，包括 jailbreak、提示注入、越狱构造、模型欺骗等；\n2. 搭建攻防评测系统，自动化运行各种恶意 prompt、隐蔽攻击、长上下文攻击等手段，识别模型漏洞；\n3. 分析攻击样本与模型行为，定位安全薄弱点，推动安全可信AI研发；\n4. 跟踪国际前沿的 LLM 攻防研究、越狱技术、对抗样本生成方法，并转化为内部测试能力；\n5. 与安全对齐、预训练团队协作，在模型迭代过程中持续进行安全性回归测试。","requirements":"1. 在大模型攻防、越狱攻击等方向有研究或工程经验；\n2. 理解大模型架构与推理机制，熟悉常见安全漏洞（幻觉、有害输出、归纳偏差等）；\n3. 熟练使用 Python，有能力构建自动化攻防测试工具链；\n4. 善于分析模型行为，能从攻击结果中抽象出可复用的漏洞模式；\n5. 有红队经验、安全攻防竞赛经历或安全研究背景者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7586567008909773098","sourceKey":"shlab_social","company":"上海AI实验室","title":"前沿AI风险算法研究员","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7586567008909773098?mode=social","duty":"1. 针对超级智能体、前沿AI智能体及AI4S智能体，研究其潜在的内生未知风险（如目标偏移、权力寻求、策略欺骗、模型逃逸等），建立具备前瞻性的风险识别、建模与形式化分析的理论框架；\n2. 设计并开发算法与系统，用于预测、评估和量化前沿AI系统在高度复杂、开放或对抗性环境下的极端风险场景与连锁效应，构建风险预警指标体系；\n3. 开展对大语言模型、自主智能体等前沿AI系统的安全性评估，推动风险防御从“事后治理”转向“前瞻预测”的研究范式突破；\n4. 研究针对超级智能和前沿模型的创新性安全对齐与风险控制方法，探索可控、可靠、可中断的人工智能架构与干预机制；\n5. 跟踪国际AI安全与风险研究最新进展，参与高水平学术交流与协作，并推动在国际顶级AI/安全会议或期刊上发表研究成果。","requirements":"1. 硕士及以上学历，计算机科学、人工智能、网络安全、数学或相关专业；\n2. 精通AI技术，对大语言模型、强化学习智能体及多智能体系统的前沿技术有深刻理解；\n3. 具备出色的数学建模或概率推理能力，能够对模糊、不确定的风险进行结构化定义与量化分析；\n4. 具备优秀的Python编程能力及AI训练框架使用经验，有处理复杂实验与仿真的能力；\n5. 具备优秀的英文文献阅读、技术研判与学术交流能力；\n6. 满足以下至少一项专业相关能力：具有AI安全对齐、AI4Science、前沿风险等相关领域的研究或项目经验；具备复杂系统建模、因果推断、形式化验证或高风险系统可靠性分析的研究背景；有深度参与大语言模型、自主智能体或AI4Science项目研发的经验，并对其潜在风险有深入思考。\n\n加分项：\n1. 在人工智能、机器学习领域的顶级会议或期刊（如NeurIPS, ICML, ICLR, AAAI, JML","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7586993002837641482","sourceKey":"shlab_social","company":"上海AI实验室","title":"推理框架开发工程师- 系统平台","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7586993002837641482?mode=social","duty":"1. 参与各种AI加速芯片接入深度学习训练与推理框架的开发工作；\n2. 运用编译、融合算子等多种技术手段，加速各种AI加速芯片上的大模型训练推理；\n3. 其他相关前沿技术的调研与运用。\n\n\n","requirements":"1. 具有良好的编程习惯，熟练使用Python/C++ 语言，有较强的debug能力；\n2. 熟悉大模型推理算法，熟悉一种或者多种推理框架（vllm, lmdeploy, sglang, lightllm等）；\n3. 对深度学习训练框架有较深理解与实践（包含不限于深度学习框架：Megatron，Pytorch，TF，JAX）；\n4. 较强的自驱动力，对先进技术有浓厚兴趣；\n5. 有较强的团队精神和沟通交流能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7594391555437480202","sourceKey":"shlab_social","company":"上海AI实验室","title":"GPU平台研发工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7594391555437480202?mode=social","duty":"1. 参与 AI 算力云原生平台整体架构设计与核心模块研发，负责训练调度、资源管理等关键子系统的设计与实现，支撑万卡级 GPU/NPU 集群的稳定运行与资源效率持续优化；\n2. 深度参与 Kubernetes 调度器的定制化开发，负责 AI 训练场景下的优先级调度、资源抢占、Gang 调度及弹性伸缩能力建设，满足大规模分布式训练与推理需求；\n3. 深度参与 AI 训练任务运行稳定性与可观测性能力建设，设计并实现基于硬件、通信及调度事件的监控、告警与故障诊断机制，提升任务异常发现效率与根因定位能力；\n4. 持续跟进云原生 AI 领域前沿技术方向（如异构算力编排、Serverless 训练等），推动技术方案的工程化验证与落地，并参与 CNCF 等开源社区的技术交流与贡献。","requirements":"核心能力：\n1. 计算机相关专业本科及以上学历，3–6 年云原生或分布式系统研发经验，参与过至少一个中大型容器平台或基础设施系统的建设；\n2. 精通 Golang 系统编程，熟悉 Kubernetes 核心组件原理，具备调度器扩展、调度插件或设备插件开发经验；\n3. 熟悉 Kubernetes 调度与资源管理机制，有 Volcano / Kubeflow / Argo 等 AI 云原生框架使用或开发经验者优先；\n4. 熟练使用 Prometheus + Grafana 构建监控与告警体系，具备性能瓶颈分析与告警规则设计经验；\n5. 具备较强的问题分析与系统定位能力，能够独立完成复杂调度异常、资源争用或性能问题的根因分析与修复。\n加分项：\n1. 有 AI 训练平台或大模型训练系统建设经验，熟悉 PyTorch 分布式训练原理；\n2. 参与过 Kubernetes 或云原生相关开源项目贡献（如","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7595097499736639753","sourceKey":"shlab_social","company":"上海AI实验室","title":"AI平台产品经理 - 科研产品平台部","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7595097499736639753?mode=social","duty":"面向科研工作者和专业用户，参与AI科研产品及大模型产品的建设，推动模型、Agent、工具、数据和工作流转化为易用、可信、可评估的产品能力。\n既能理解用户，又能理解AI：不仅能够撰写需求文档，还能借助AI编程工具快速验证想法，并通过系统评测判断产品是否真正有效。\n\n岗位职责\n1. 负责AI科研产品竞品研究、技术趋势分析、用户研究、需求分析、产品规划、方案设计和迭代落地。深入科研人员和专业用户的真实工作流程，识别高价值任务、关键痛点和AI可介入环节。\n2. 参与科学发现平台产品建设。将大模型、工具调用、知识检索、数据分析和智能体能力转化为用户可理解、可操作的产品体验。\n3. 设计核心使用链路和关键交互，持续优化产品的上手效率、任务完成质量和用户体感。使用AI编程和原型工具快速构建可交互原型，完成需求验证、方案比较和用户测试。\n4. 建立AI产品评测体系，从任务完成度、准确性、稳定性、可用性、效","requirements":"1. 本科及以上学历，2年以上AI产品、专业工具、平台产品或复杂用户产品经验。\n2. 具备较强的用户洞察、需求分析和产品设计能力，能够将复杂能力转化为清晰易用的产品。\n3. 对 Agent、大模型、RAG工具调用及模型评测有基本理解，能够与算法和研发团队有效协作。\n4. 具备完整产品经验，能够从问题定义、方案设计、开发跟进、上线验证到数据复盘推动闭环。\n5. 具备较强的结构化分析和逻辑表达能力，能够明确产品目标、使用场景和验收标准。\n6. 对产品体验敏感，能够发现交互摩擦、结果不可信和用户预期落差等问题。\n7. 主动性强，善于在不确定条件下快速验证，而不是等待所有信息完备后才开始行动。\n8. 对科研工作方式和AI for Science有兴趣，愿意持续学习不同学科的任务特点。\n\n优先条件\n- 熟练使用Cursor、Claude Code、Codex等AI编程工具，能通过Vibe Codin","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7615234376275773734","sourceKey":"shlab_social","company":"上海AI实验室","title":"大模型训练算法工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7615234376275773734?mode=social","duty":"1.负责垂直领域大模型的全流程训练工作，独立执行增量预训练（CPT）、监督微调（SFT）及强化学习对齐（RLHF/DPO）任务\n2.负责高质量训练数据的构建与清洗，包括预训练语料的清洗过滤、SFT指令数据的构造与配比、偏好数据的生成\n3.基于Ascend NPU/NV GPU平台，使用Megatron-LM、veRL、LLaMA-Factory等框架进行模型训练与性能调优\n4.监控训练过程，及时发现并解决Loss异常、梯度爆炸等常见训练问题，产出实验分析报告\n5.参与模型评测工作，根据评测结果调整数据配比与超参数，持续提升模型在垂域的效果\n6.跟踪大模型训练领域前沿进展，复现SFT/RLHF相关论文算法，并尝试应用到业务场景中","requirements":"1.计算机、人工智能、数学等相关专业硕士及以上学历，具备1~2年NLP或大模型算法工作经验\n2.熟悉Python、PyTorch，对Transformer架构原理（Attention、RoPE等）和主流开源LLM（Qwen、LLaMA、InternLM等）有深入了解\n3.具备大模型（7B及以上）微调实战经验，并具备以下任一方向的技术积累：\n-预训练/CPT方向：熟悉分布式训练基础（DP/TP/PP），有使用Megatron-LM或DeepSpeed进行多机多卡训练的经验\n-后训练方向：熟悉SFT、RLHF、DPO等算法流程，有过完整的模型精调与对齐实践，了解PPO算法细节\n4.具备良好的实验习惯，能够独立设计对比实验，对数据质量和超参敏感，能通过Badcase分析定位问题\n5.有大模型相关的开源项目贡献、顶会论文发表或知名比赛（Kaggle、天池等）获奖经历者优先\n6.具备团队协作意识，能","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7626655853009406217","sourceKey":"shlab_social","company":"上海AI实验室","title":"保密管理岗-保密办公室","city":"上海","category":"职能类","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7626655853009406217?mode=social","duty":"1. 负责保密日常教育素材收集、保密常识常态化宣贯，完成保密宣传小报制作、国家安全宣传教育日等专项活动策划落地；会同人力资源部门落实年度保密培训计划，完成培训通知、资料发放、组织实施及全流程台账记录归档。\n2. 监督涉密载体接收、登记、传阅、保管、清退、归档、销毁全流程的审批办理与合规检查，规范整理并归档全周期管理材料，确保涉密载体全程可追溯、全环节合规。\n3. 按保密管理要求，常态化开展实验室非密计算机及网络、涉密信息设备的日常使用合规性检查，严格落实专人专管、审查审批、账物相符的管理要求，形成闭环检查记录。\n4. 协助落实年度保密工作计划，常态化开展泄密风险与安全隐患排查，规范做好日常巡查记录；受理各部门日常保密咨询、发布保密风险提醒，指导协助各部门规范处理涉密事项。\n5. 配合完成上级单位保密专项检查、机构保密自查自评、问题整改落实等全流程工作，规范整理归档相关材料，确保各项工作符合","requirements":"1. 学历专业：硕士及以上学历，保密管理、行政管理、法学、信息安全、档案管理等相关专业优先。\n2. 经验背景：3 年及以上保密管理、涉密合规相关工作经验；有科研机构、高新技术企业、军工单位、政府事业单位保密管理工作经验，熟悉人工智能科研场景保密要求、持有保密管理相关资格证书者优先。\n3. 专业技能：精通 Office 办公软件，具备宣传物料制作、台账规范化管理、公文撰写能力；熟练掌握国家保密法律法规，熟悉涉密载体、涉密信息设备与网络的保密管理规范，掌握保密检查、风险排查的核心流程与方法。\n4. 核心素养：具备极强的保密意识与底线思维，严守保密纪律，原则性强；工作细致严谨、责任心强，具备良好的沟通协调、闭环执行与问题排查能力；抗压能力强，可适配阶段性高强度专项工作，具备快速学习与合规落地能力。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7637155354942228779","sourceKey":"shlab_social","company":"上海AI实验室","title":"物质科学青年研究员/算法工程师","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7637155354942228779?mode=social","duty":"1、探索人工智能与物质科学相关自然科学研究课题的结合，致力于提出新的研究方法与技术路径；\n2、参与科学智能的大模型开发和训练，开发和优化适用于物质科学问题的AI模型与开源AI工具，持续提升模型性能；\n3、跟踪国际前沿研究动态，推动研究方向的拓展与深化，打造和提升行业技术影响力。","requirements":"1、具有物理、计算化学、计算机科学、人工智能、数学等相关专业博士学位；\n2、对AI for science领域的前沿研究充满热情，渴望通过技术推动科学进步，在相关领域有突出研究成果，如Nature、Science或重要子刊、PR系列上的论文发表，或发表人工智能领域顶会论文；\n3、拥有良好的沟通与团队协作能力，能够与跨学科团队高效合作；\n4、具备极强的自主探索、解决问题的能力和精神，针对研究过程中遇到的实际问题能够自主寻找解决方案。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7638161559856253220","sourceKey":"shlab_social","company":"上海AI实验室","title":"组织文化岗","city":"上海","category":"职能通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7638161559856253220?mode=social","duty":"1、文化阵地与品牌运营： 构建多维文化传播矩阵，通过新媒体等手段策划并推行文化项目，实现实验室品牌传播与文化传承的深度融合。\n2、组织沟通与信息公开： 搭建多层级员工沟通桥梁，策划并落地“决策透明化”相关机制，打造真实、互信的管理文化与职场氛围。\n3、员工关怀与能量场营造： 整合内外部资源，统筹员工文体活动与健康管理项目；通过陪伴式成长方案，提升员工幸福感与组织粘性。\n4、组织氛围感知与诊断： 运用结构化方法进行组织“体检”，精准感知员工需求与士气波动，输出专项分析报告为管理层决策提供支撑。\n5、大型项目全案策划： 统筹策划并执行年会、运动会、开放日及各类大型展会会务；负责全流程质量管控与传播效果最大化。","requirements":"1、学历背景： 全日制本科及以上学历；具备 3 年以上组织文化或品牌公关相关工作经验。\n2、核心能力： 具备极强的文字功底与活动策划能力，能够独立输出高质量的推文、视频及活动方案；熟悉新媒体运营逻辑。\n3、沟通影响力： 具备出色的组织沟通与资源整合能力，擅长跨部门协调，能够快速与各层级员工建立信任。\n4、综合素养： 性格开朗热情，具备较强的亲和力与同理心；正直诚信，能够在高压环境下保持积极乐观的职业态度。\n5、特质优先： 熟悉互联网文化传播手段；有科技/人工智能行业背景或大型文化项目成功案例者优先。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7641171481333958931","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】VLA具身操作智能Tech Lead","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7641171481333958931?mode=social","duty":"1. 技术战略与架构规划\n- 制定VLA技术中长期发展路线图，明确技术攻关方向与产品落地路径\n- 主导VLA技术体系整体架构设计，涵盖视觉感知、语言理解、动作生成全流程\n- 评估技术可行性、风险与商业价值，确保技术路线的先进性与可落地性\n2. 核心技术研发与攻坚\n- 主导VLA核心技术难题攻关，包括：VLA泛化性、世界动作模型协同、多模态语义对齐等\n- 研发端到端VLA架构，实现高层任务规划与低层动作生成的模态对齐\n- 构建物理世界模型（World Model），解决仿真到现实的泛化鸿沟（Sim2Real）\n- 开发扩散/自回归策略生成多模态动作轨迹，满足机器人实时控制需求\n3. 团队建设与管理\n- 负责VLA技术团队的组建、培养与管理，明确团队分工（算法研发、工程实现、系统集成）\n- 建立高效的研发体系与激励机制，打造兼具技术深度与协作能力的核心团队\n- 负责团队人才招聘、培养、绩效评估","requirements":"硬性要求\n1. 教育与专业背景\n- 硕士及以上学历（博士优先），计算机科学、人工智能、机器人学、自动化等相关专业\n2. 工作经验\n- 5年以上VLA/多模态算法研发经验，其中至少2年以上技术管理经验\n- 具备VLA项目实际交付经验，有可验证的项目成果（技术报告、项目网站、媒体报道等）\n- 有物流分拣、实验室自动化、仓储机器人等相关场景落地经验者优先\n3. 核心技术能力\n- VLA技术深度：精通视觉-语言-动作多模态融合算法，熟悉CNN/Transformer、扩散模型、强化学习等技术\n- 算法实现能力：熟练运用PyTorch/TensorFlow、ROS 2、MuJoCo等工具框架\n- 工程部署能力：具备CUDA/TensorRT模型加速与部署优化经验，熟悉边缘计算设备优化策略\n- 系统集成能力：熟悉机器人操作系统，具备机器人系统端到端落地能力\n4. 学术成果（学术背景候选人）\n- 在VL","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7641979533869107483","sourceKey":"shlab_social","company":"上海AI实验室","title":"材料科学数据青年研究员/工程师","city":"上海","category":"工程通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7641979533869107483?mode=social","duty":"- 负责大模型预训练与微调数据的构建，搭建材料AI-ready数据，设计结构化数据、知识图谱等AI-ready数据构建的智能体系统。\n- 对接材料科学一线研究人员与湿实验团队，提炼真实科研需求，设计材料数据标注规则与评估体系。\n- 与预训练团队协同，通过数据迭代优化模型效果。","requirements":"- 计算机科学、材料学、计算物理学等相关专业硕士及以上学历。\n- 扎实的材料科学背景：实际使用过MP、AFlow、NIST、NIMS等材料数据库。\n- 有过材料/化学语言模型（ChemLLM、MolFormer、MatChat 等）或 MatterGen相关工具的实操经验。\n- 具有高通量实验数据解析经验，或参与过自动化实验平台数据对接。","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7644148881353296171","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】世界模型方向Tech Lead","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7644148881353296171?mode=social","duty":"核心目标\n- 构建充分理解物理世界规律、生成物理环境的、原生安全的基础模型和支撑软件系统。\n- 搭建面向科学实验室3D物理环境的生成式基础模型与软件系统；研发面向科学发现的融入物理数据与规律的世界模型。\n岗位职责\n1. 技术战略与架构规划\n- 制定物理世界模型的技术路线图，定义差异化技术方向\n- 设计面向科学发现的多模态模拟器架构\n- 规划物理智能基础模型的技术演进路径，探索替代大语言模型的新一代模型架构\n2. 核心技术研发\n- 领导团队在以下至少一个方向进行深度技术攻关：\n  - 3D空间智能：构建面向物理世界的3D感知、理解与生成能力\n  - 物理世界模型：面向科学发现的融入物理数据与规律的世界模型\n  - 多模态理解与生成：文本、图像、视频、动态场景的跨模态建模\n- 推动生成式AI技术在物理世界模拟中的应用，包括扩散模型、生成对抗网络等前沿技术\n- 负责大模型的微调、优化与部署，构建","requirements":"基本要求\n- 国内外知名高校计算机、人工智能、机器人、自动化等相关专业博士学历\n- 同时具备有学术积累和工程化产出能力\n技术能力要求\n- 核心技术栈：\n  - 深入理解大语言模型、扩散模型、生成对抗网络等生成式AI技术\n  - 熟悉多模态融合、跨模态理解与生成技术\n  - 具备物理模拟、机器人控制、3D视觉等相关领域知识\n- 工程能力：\n  - 熟练掌握主流AI开发框架\n  - 具备大规模AI系统设计、优化与部署经验\n  - 熟悉分布式训练、模型压缩、推理加速等技术\n- 研究方向：在以下至少一个方向有深入研究：\n  - 数据工程与大规模数据采集处理\n  - 算法设计与模型训练优化\n  - 多模态生成与物理世界建模\n管理与领导能力\n- 具备技术团队的管理经验，或作为核心骨干承担过技术负责人角色\n- 能够制定清晰的技术路线，有效拆解复杂任务，推动项目落地\n- 具备优秀的沟通协调能力，能够跨团队","description":"","jdComplete":true,"sourceStatus":"1"},{"id":"shlab_social:7644504289545242934","sourceKey":"shlab_social","company":"上海AI实验室","title":"【高阶岗位】硬件系统青年/资深科学家","city":"上海","category":"科研通道","channels":["social"],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://www.shlab.org.cn/joinus/detail/7644504289545242934?mode=social","duty":"1. 嵌入式系统开发\n负责机器人本体嵌入式软件架构设计与开发，包括基于Linux/RTOS的底层驱动开发、实时通信中间件（如ROS/ROS2、DDS）集成、多传感器数据采集与同步模块开发。\n2. 硬件平台搭建与集成\n主导机械臂、轮式机器人、无人机等硬件平台的电控系统设计，完成主控芯片/嵌入式计算单元（如Jetson、RK3588等）的选型、电路设计审查与硬件调试，确保算力与功耗平衡。\n3. 传感器系统融合\n负责可见光相机、红外传感器、深度相机（ToF/结构光）、IMU、激光雷达等多传感器硬件接入与驱动开发，实现多源异构数据的硬件级同步与预处理。\n4. 运动控制与部署\n参与机器人底层运动控制算法部署，包括关节电机控制、轮式/足式底盘驱动、轨迹跟踪与力控模块的嵌入式实现，保障控制实时性与稳定性。\n5. 系统集成与调试\n负责算法团队模型在本体上的部署对接与性能优化，完成软硬件联调、外场测试与问题","requirements":"1. 学历背景：\n博士及以上学历，电子信息工程、自动化、计算机、机械电子等相关专业；优秀硕士且有丰富项目经验者可放宽。\n2. 工作经验：\n  - 5年以上机器人导航 / 视觉语言导航 / 多模态算法研发经验\n  - 3年以上技术团队管理经验，有从0到1搭建团队或主导核心项目交付的经验\n3. 技术能力：\n  - 嵌入式软件开发：精通C/C++，熟悉Linux内核、设备驱动开发、实时操作系统（RTOS）；熟练掌握ROS/ROS2框架及通信机制\n  - 硬件设计能力：熟悉ARM/DSP等嵌入式处理器架构，具备PCB设计审查、硬件调试与信号完整性分析能力；了解电源管理、电机驱动等模拟电路设计\n  - 传感器与感知：熟悉常用机器人传感器（相机、IMU、激光雷达、编码器等）的硬件接口与驱动开发，有多传感器时间同步与数据融合经验者优先\n  - 运动控制基础：了解PID、MPC、运动学/动力学建模等基础控","description":"","jdComplete":true,"sourceStatus":"1"}];
